source_stop.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import { createHash } from 'node:crypto';
const hash = p => createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const basePath = 'docs/remediation/design/W32.04/baseline.json';
const base = JSON.parse(fs.readFileSync(basePath, 'utf8'));
const owned = new Set(base.owned.map(x => x.path));
const files = base.owned.map(x => ({ path: x.path, sha256: hash(x.path) }));
const protectedFiles = base.pins.filter(x => !owned.has(x.path)).map(x => ({ path:x.path, expected:x.sha256, actual:hash(x.path) }));
const changed = protectedFiles.filter(x => x.expected !== x.actual);
const out = { final_source_stop: { at: new Date().toISOString(), files }, protected_source_comparison: { checked:protectedFiles.length, matched:protectedFiles.length-changed.length, mismatches:changed }, references: { baseline:{path:basePath,sha256:hash(basePath)}, plan:{path:'docs/remediation/design/W32.04/plan.md',sha256:hash('docs/remediation/design/W32.04/plan.md')}, admission:{path:'docs/remediation/evidence/W32.04/admission.json',sha256:hash('docs/remediation/evidence/W32.04/admission.json')} } };
console.log(JSON.stringify(out,null,2));
if(changed.length)process.exitCode=1;
NODE
